"""Record selected production paths during the public lifecycle diagnostic."""
import atexit,collections,json,runpy
from pathlib import Path
import hipengine.runtime.qwen4_exp_batch_qsa as qa
from hipengine.runtime.qwen4_exp_batch_qsa_index import Qwen4ExpBatchQsaIndexState as Index
counts=collections.Counter(); original=qa.batch_qsa_attention_implementation

def record(label):
 counts[label]+=1
 # Persist first engagement; the server can exit without running atexit hooks.
 if counts[label]==1:save()

def choose(**geometry):
 result=original(**geometry);record(result[1]);return result
qa.batch_qsa_attention_implementation=choose
for name in ('select_active','select_active_device'):
 def wrap(fn,label):
  def call(*args,**kwargs):record(label);return fn(*args,**kwargs)
  return call
 setattr(Index,name,wrap(getattr(Index,name),name))
@atexit.register
def save():Path('/tmp/qwen38fn-decode-20261022/public-path-counts.json').write_text(json.dumps(dict(counts),indent=2)+'\n')
runpy.run_module('hipengine.server',run_name='__main__')
